// Normalize and validate incoming ticket payload
const body = $input.first().json.body || $input.first().json;

const ticketId = body.ticket_id || `TICKET-${Date.now()}`;
const customerName = body.customer_name || 'Unknown Customer';
const email = body.email || 'user@example.com';
const subject = body.subject || 'No Subject';
const message = body.message || body.text || body.content || '';
const priority = body.priority || 'normal';
const createdAt = body.created_at || new Date().toISOString();

if (!message || message.trim().length === 0) {
  throw new Error('Ticket message body is empty or missing.');
}

return [{
  json: {
    ticket_id: ticketId,
    customer_name: customerName,
    email: email,
    subject: subject,
    message: message.trim(),
    priority: priority,
    created_at: createdAt,
    processed_at: new Date().toISOString()
  }
}];

// Parse AI JSON response and append routing decision
const ticketData = $('Normalize Ticket Data').first().json;
const aiContent = $input.first().json.message?.content
  || $input.first().json.choices?.[0]?.message?.content
  || '';

let analysis;
try {
  const clean = aiContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analysis = JSON.parse(clean);
} catch (e) {
  analysis = {
    anger_score: 5,
    sentiment_category: 'NEUTRAL',
    emotion_summary: 'AI response could not be parsed. Manual review required.',
    key_issues: ['Parse error'],
    urgency_level: 'MEDIUM',
    recommended_action: 'Review ticket manually'
  };
}

const angerScore = Math.min(10, Math.max(0, parseInt(analysis.anger_score, 10) || 5));

let routing_channel, routing_reason;
if (angerScore >= 8) {
  routing_channel = '#escalation';
  routing_reason = 'Score ≥8 — immediate escalation required';
} else if (angerScore >= 4) {
  routing_channel = '#support';
  routing_reason = 'Score 4–7 — standard support handling';
} else {
  routing_channel = '#feedback';
  routing_reason = 'Score ≤3 — feedback or general inquiry';
}

return [{
  json: {
    ...ticketData,
    anger_score: angerScore,
    sentiment_category: analysis.sentiment_category || 'NEUTRAL',
    emotion_summary: analysis.emotion_summary || '',
    key_issues: analysis.key_issues || [],
    urgency_level: analysis.urgency_level || 'MEDIUM',
    recommended_action: analysis.recommended_action || '',
    routing_channel,
    routing_reason,
    analyzed_at: new Date().toISOString()
  }
}];
